head.script:
scwin.screenId = "jldstf10003_html5";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "tocIframe", attr: "src", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("tocUrl"))); } },
        { childId: "tocIframe_2", attr: "src", fn: function () { return "/dsclproc/JLDSTF10005_toc.jsp?body_url=" + String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("tocUrl"))) + "&acpt_no=" + String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("acptNo"))); } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_attrReals();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf10003_html5.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.img_19_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_19_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_19_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.displayToc('close')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf10003_html5.img_19_onclick' }); }
};

/**
 * @event
 * @name scwin.img_28_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_28_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_28_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.displayToc('open')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf10003_html5.img_28_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.checkToc
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkToc = function () {
    /* sdd-asis-lifecycle:begin checkToc — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const winHeight = innerHeight;
    $c.util.getComponent('tocIframe').height = winHeight + "px";
    $c.util.getComponent('bodyIframe').height = winHeight - 13 + "px";
    const isToc = 'null';
    const isIFRS = 'null';
    if (isToc === "Y" || isIFRS === "Y") {
        scwin.displayToc('open');
    } else {
        scwin.displayToc('close');
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.displayToc
 * @author Inswave
 * @date 2026. 09. 29
 * @param command
 * @returns
 * @hidden N
*/
scwin.displayToc = function (command) {
    /* sdd-asis-lifecycle:begin displayToc — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (command === "close") {
        $c.util.getComponent("tocTd").width = "16";
        ($c.util.getComponent("openToc") && $c.util.getComponent("openToc").hide ? $c.util.getComponent("openToc").hide() : console.warn('[sdd] hide 대상 미해결: ' + "openToc"));
        ($c.util.getComponent("closeToc") && $c.util.getComponent("closeToc").show ? $c.util.getComponent("closeToc").show() : console.warn('[sdd] show 대상 미해결: ' + "closeToc"));
    } else {
        if (command === "open") {
            $c.util.getComponent("tocTd").width = "210";
            ($c.util.getComponent("openToc") && $c.util.getComponent("openToc").show ? $c.util.getComponent("openToc").show() : console.warn('[sdd] show 대상 미해결: ' + "openToc"));
            ($c.util.getComponent("closeToc") && $c.util.getComponent("closeToc").hide ? $c.util.getComponent("closeToc").hide() : console.warn('[sdd] hide 대상 미해결: ' + "closeToc"));
        }
    }
    /* sdd-asis-lifecycle:end */
};
